insert into hero_profiles (slug, is_meta, ban_recommended, tags, ban_note, notes, power_early, power_mid, power_late, status) values
  ('lukas', true, true, array['rush', 'dash', 'thick']::text[], 'Meta fighter; sustain solo-queue teams can''t burst through.', 'CC immune while dashing (so Khufra doesn''t stop him). Skill lifesteal — buy Dominance Ice.', null, null, null, 'confirmed'),
