  ('masha', true, true, array['thick']::text[], 'Meta fighter; extremely hard to burst.', 'Multiple HP bars make her very hard to burst.', null, null, null, 'confirmed'),
  ('paquito', true, true, array['dash']::text[], 'Very strong; dominates the early game.', 'Early game super strong. Bush presence is hard to deal with.', 5, null, null, 'confirmed'),
  ('marcel', true, true, array['frontline']::text[], 'Meta roamer; time-stop ultimate wins teamfights.', 'Converts health into defense — answer with burst true damage. Diggie and Purify do NOT cancel his ultimate.', null, null, null, 'confirmed'),
  ('hirara', true, true, array['dash']::text[], 'Meta jungler; dominates the early game.', '', 5, null, null, 'confirmed'),
  ('belerick', true, true, array['thick', 'frontline', 'slow_teamfight']::text[], 'Insane durability and CC; needs true damage to answer.', 'Ultimate reflects damage. Late-game tank.', null, null, 5, 'confirmed'),
  ('carmilla', true, true, array['frontline']::text[], 'Top roam pick; strong teamfight lockdown.', 'Diggie does NOT break her blood link.', null, null, null, 'confirmed'),
  ('alice', true, true, array[]::text[], 'Especially dangerous paired with Angela.', '', null, null, null, 'confirmed'),
  ('hanzo', true, false, array[]::text[], '', 'Mid-game power.', null, 5, null, 'confirmed'),
  ('gloo', true, true, array['frontline', 'thick']::text[], 'Strong; ban if you have no Faramis/Vexana/Winter Crown answer.', '', null, null, null, 'confirmed'),
  ('atlas', true, false, array['frontline', 'thick']::text[], '', 'Very strong presence (CC ultimate control) but doesn''t need a ban.', null, null, null, 'confirmed'),
