  ('rafaela', false, false, array['enchanter']::text[], '', 'Overrated — not ban-worthy. Falls apart without a tank.', null, null, null, 'confirmed'),
  ('floryn', false, false, array['enchanter']::text[], '', 'Needs a tank to function.', null, null, null, 'confirmed'),
  ('sun', false, false, array['split']::text[], '', 'Pushes extremely fast; usually must be answered, but rotating more than one hero loses tempo.', null, null, null, 'confirmed'),
  ('dyrroth', false, false, array['anti_tank', 'true_damage']::text[], '', 'VERY strong early, weak late.', 5, 3, 1, 'confirmed'),
  ('alpha', false, false, array['anti_tank', 'true_damage']::text[], '', 'Good in familiar hands; must land ultimate. Bad into heavy kiting or healing (e.g. Estes).', null, null, null, 'confirmed'),
  ('karrie', false, false, array['anti_tank', 'true_damage', 'dash']::text[], '', 'Best vs 2+ thick heroes. Has a dash, so survives divers better than Lesley.', null, null, null, 'confirmed'),
  ('lesley', false, false, array['anti_tank', 'true_damage']::text[], '', 'Long-range true damage; bad when the enemy closes distance fast (e.g. Yu Zhong).', null, null, 5, 'confirmed'),
  ('x-borg', false, false, array['anti_tank', 'true_damage']::text[], '', 'Heavy true damage vs tanks, but too slow as burst.', null, null, null, 'confirmed'),
