  ('cecilion', false, false, array['anti_tank']::text[], '', 'Late-game mid option vs tanks.', null, null, 5, 'confirmed'),
  ('valir', false, false, array['anti_walking']::text[], '', 'Great vs drafts with lots of walking heroes; best mage answer to Sun''s split push.', null, null, null, 'confirmed'),
  ('khufra', false, false, array['anti_dash', 'frontline']::text[], '', 'Stops dashes — but not Lukas (CC immune while dashing).', null, null, null, 'confirmed'),
  ('minsitthar', false, false, array['anti_dash']::text[], '', 'Ultimate stops dashes.', null, null, null, 'confirmed'),
  ('obsidia', false, false, array[]::text[], '', 'Hard counters dash heroes.', null, null, null, 'confirmed'),
  ('karina', false, false, array[]::text[], '', 'Very strong counter to Obsidia — check the rest of the draft. Karina''s own counters still to note.', null, null, null, 'confirmed'),
  ('yu-zhong', false, false, array['thick']::text[], '', 'Closes distance fast — punishes Lesley.', null, null, 5, 'confirmed'),
  ('ling', false, false, array[]::text[], '', '', null, null, 5, 'confirmed'),
  ('granger', false, false, array[]::text[], '', 'Fast tempo.', 4, null, null, 'confirmed'),
  ('hilda', false, false, array['rush', 'thick']::text[], '', 'Fast tempo.', 4, null, null, 'confirmed'),
  ('kalea', false, false, array['pickoff']::text[], '', '', null, null, null, 'confirmed'),
